def is_point_on_segment(p, a, b):
    # Check if point p is collinear with a and b
    def is_collinear(p, a, b):
        # Cross product to check collinearity
        return (p[0] - a[0]) * (b[1] - a[1]) == (p[1] - a[1]) * (b[0] - a[0])

    # Check if p lies within the bounding box of a and b
    def is_between(p, a, b):
        return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0])) and (min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    return is_collinear(p, a, b) and is_between(p, a, b)
```

