def is_convex_polygon(points):
    def cross(p, q, r):
        # Compute the cross product of vectors (q - p) and (r - q)
        return (q[0] - p[0]) * (r[1] - q[1]) - (q[1] - p[1]) * (r[0] - q[0])

    n = len(points)
    if n < 3:
        return False

    # To check if all cross products have the same sign (all left or all right turns)
    sign = 0
    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        c = cross(p, q, r)
        if c == 0:
            # Collinear points, not considered convex
            return False
        if c > 0:
            if sign == -1:
                return False
            sign = 1
        else:
            if sign == 1:
                return False
            sign = -1
    return True
```

