def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Convert requests to a set for O(1) lookups
    request_set = set(requests)

    # Initialize the list of stops with the start_floor if it's requested
    stops = []
    if start_floor in request_set:
        stops.append(start_floor)

    # Determine the end floor based on direction
    end_floor = top_floor if direction == 1 else 1

    # If start_floor is already the end floor, return early
    if start_floor == end_floor:
        return stops

    # Generate all floors in the path from start_floor to end_floor
    if direction == 1:
        # Moving up: from start_floor to top_floor inclusive
        for floor in range(start_floor + 1, top_floor + 1):
            if floor in request_set:
                stops.append(floor)
    else:
        # Moving down: from start_floor to 1 inclusive
        for floor in range(start_floor - 1, 0, -1):
            if floor in request_set:
                stops.append(floor)

    return stops
```

