def queue_with_capacity_serve(events, capacity):
    queue = []
    for event in events:
        if event[0] == "arrive":
            person_id = event[1]
            queue.append(person_id)
        elif event[0] == "serve":
            # Remove up to `capacity` people from the front of the queue
            remove_count = min(len(queue), capacity)
            queue = queue[remove_count:]
    return queue
```

